/**
 * Shapes drawn from the real Zugerberg skyline (src/data/zugerberg.json,
 * generated by tools/terrain/panorama.py).
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const sceneData = JSON.parse(
  readFileSync(fileURLToPath(new URL('../data/zugerberg.json', import.meta.url)), 'utf8'),
);

const round = (v) => Math.round(v * 10) / 10;

function theta(layer, az) {
  const f = (az - sceneData.az0) / layer.step;
  const i = Math.max(0, Math.min(layer.th.length - 2, Math.floor(f)));
  const t = Math.min(1, Math.max(0, f - i));
  return (layer.th[i] * (1 - t) + layer.th[i + 1] * t) / 100;
}

/**
 * The Zugerberg's silhouette as the top edge of a content sheet:
 * a path in a 1000 x 64 box, filled to the bottom.
 */
export function ridgeEdgePath({ from = 66, to = 172, points = 220 } = {}) {
  const [near, crest] = sceneData.layers;
  const samples = [];
  for (let i = 0; i <= points; i += 1) {
    const az = from + ((to - from) * i) / points;
    samples.push(Math.max(theta(near, az), theta(crest, az)));
  }
  const lo = Math.min(...samples);
  const hi = Math.max(...samples);
  const d = samples
    .map((th, i) => `${i ? 'L' : 'M'}${round((i / points) * 1000)} ${round(62 - ((th - lo) / (hi - lo)) * 58)}`)
    .join('');
  return `${d}L1000 64L0 64Z`;
}

/**
 * A still drawing of the same view at dusk, shown behind the page until the
 * live scene starts (and in place of it without JavaScript).
 */
export function staticBackdropSvg() {
  const W = 1600;
  const H = 1000;
  const hy = 630;
  const k = W / 140;
  const ex = 2.8;
  const c0 = 132;
  const x = (az) => round(W / 2 + (az - c0) * k);
  const y = (th) => round(hy - th * k * ex);
  const fills = ['#1b2430', '#2a3346', '#3b4560', '#5a6283', '#7a7c9c'];
  const paths = sceneData.layers
    .map((layer, i) => {
      const pts = [];
      for (let az = c0 - 72; az <= c0 + 72; az += 0.5) pts.push(`${x(az)} ${y(theta(layer, az))}`);
      return { i, d: `M${x(c0 - 72)} ${hy + 2}L${pts.join('L')}L${x(c0 + 72)} ${hy + 2}Z` };
    })
    .reverse()
    .map(({ i, d }) => `<path fill="${fills[i]}" d="${d}"/>`)
    .join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMax slice">
<defs>
<linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#121c36"/><stop offset=".6" stop-color="#3a3d63"/><stop offset="1" stop-color="#b98a8f"/></linearGradient>
<linearGradient id="l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5a5674"/><stop offset="1" stop-color="#0d1424"/></linearGradient>
</defs>
<rect width="${W}" height="${hy + 2}" fill="url(#s)"/>${paths}<rect y="${hy}" width="${W}" height="${H - hy}" fill="url(#l)"/>
</svg>
`;
}

/**
 * The social sharing image: the same skyline at dusk, mirrored in the lake,
 * with the wordmark in the sky. Rendered to PNG by tools/render-images.mjs.
 */
export function ogImageSvg(wordmarkSvg) {
  const W = 1200;
  const H = 630;
  const hy = 430;
  const k = W / 120;
  const ex = 2.6;
  const c0 = 124;
  const x = (az) => round(W / 2 + (az - c0) * k);
  const y = (th) => round(hy - th * k * ex);
  const fills = ['#161d2b', '#252d42', '#36405c', '#56607f', '#7b7f9e'];
  const paths = sceneData.layers
    .map((layer, i) => {
      const pts = [];
      for (let az = c0 - 62; az <= c0 + 62; az += 0.25) pts.push(`${x(az)} ${y(theta(layer, az))}`);
      return { i, d: `M${x(c0 - 62)} ${hy + 1}L${pts.join('L')}L${x(c0 + 62)} ${hy + 1}Z` };
    })
    .reverse()
    .map(({ i, d }) => `<path fill="${fills[i]}" d="${d}"/>`)
    .join('');
  // The wordmark's own viewBox, scaled into the sky.
  const vb = (wordmarkSvg.match(/viewBox="([^"]+)"/) || [])[1].split(/\s+/).map(Number);
  const inner = wordmarkSvg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
  const ww = 430;
  const s = ww / vb[2];
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
<defs>
<linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#101a33"/><stop offset=".55" stop-color="#3a3d66"/><stop offset="1" stop-color="#c79a92"/></linearGradient>
<linearGradient id="l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6c6584" stop-opacity=".55"/><stop offset="1" stop-color="#0c1322" stop-opacity=".96"/></linearGradient>
<radialGradient id="g" cx="${x(112)}" cy="${hy}" r="520" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#f0b48c" stop-opacity=".35"/><stop offset="1" stop-color="#f0b48c" stop-opacity="0"/></radialGradient>
</defs>
<rect width="${W}" height="${hy + 1}" fill="url(#s)"/>
<rect width="${W}" height="${hy + 1}" fill="url(#g)"/>
<g color="#f6f3ee" transform="translate(${(W - ww) / 2} 62) scale(${round(s * 10000) / 10000}) translate(${-vb[0]} ${-vb[1]})">${inner}</g>
${paths}
<g transform="matrix(1 0 0 -0.8 0 ${round(1.8 * hy)})" opacity=".9">${paths}</g>
<rect y="${hy}" width="${W}" height="${H - hy}" fill="url(#l)"/>
</svg>
`;
}
